package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.Bundle;public final class SimpleHomeActivity extends Activity{@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_simple_home);findViewById(R.id.pageBack).setOnClickListener(v->finish());findViewById(R.id.openFull).setOnClickListener(v->finish());findViewById(R.id.openSale).setOnClickListener(v->startActivity(new Intent(this,SaleActivity.class)));findViewById(R.id.openRepair).setOnClickListener(v->startActivity(new Intent(this,DirectPartSaleActivity.class)));findViewById(R.id.openShift).setOnClickListener(v->startActivity(new Intent(this,ClosingActivity.class)));findViewById(R.id.openHandover).setOnClickListener(v->startActivity(new Intent(this,RepairActivity.class)));}}